package com.paytaxihub.entity;
import jakarta.persistence.*;
@Entity @Table(name="Vehicle") public class Vehicle { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer vehicleId; @ManyToOne @JoinColumn(name="driver_id") private Driver driver; private String registrationNumber,vehicleModel; @ManyToOne @JoinColumn(name="fleet_owner_id") private FleetOwner fleetOwner; @Enumerated(EnumType.STRING) private VehicleStatus vehicleStatus; public enum VehicleStatus{Active,Inactive,Maintenance} public Vehicle(){} public Integer getVehicleId(){return vehicleId;} public void setVehicleId(Integer v){vehicleId=v;} public Driver getDriver(){return driver;} public void setDriver(Driver v){driver=v;} public String getRegistrationNumber(){return registrationNumber;} public void setRegistrationNumber(String v){registrationNumber=v;} public FleetOwner getFleetOwner(){return fleetOwner;} public void setFleetOwner(FleetOwner v){fleetOwner=v;} public String getVehicleModel(){return vehicleModel;} public void setVehicleModel(String v){vehicleModel=v;} public VehicleStatus getVehicleStatus(){return vehicleStatus;} public void setVehicleStatus(VehicleStatus v){vehicleStatus=v;} }
